insert into public.catalog_library_mandates(library_id,organization_id,status,valid_from,policy_version,created_by)values('f2180000-0000-4000-8000-000000000010','b2030000-0000-4000-8000-000000000001','ACTIVE',now()-interval'1 day',1,'a2030000-0000-4000-8000-000000000001');
set local session_replication_role=replica;
insert into public.franchise_mandate_versions(id,franchise_id,territory_version_id,economic_rule_version_id,version,mandate_status,rights_snapshot,obligations_snapshot,contract_snapshot,entry_fee_minor,entry_fee_mode,entry_fee_term_months,franchisee_share_bps,neoxa_share_bps,matricia_share_bps,distribution_basis,effective_from,content_hash,created_by)
select 'd2220000-0000-4000-8000-000000000001',id,'d2230000-0000-4000-8000-000000000001','d2240000-0000-4000-8000-000000000001',1,'ACTIVE','{}','{}','{}',0,'EXEMPT',0,5000,2500,2500,'DISTRIBUTABLE_PROFIT',now()-interval'1 day',repeat('a',64),created_by from public.franchises where id='d2030000-0000-4000-8000-000000000001';
update public.franchises set current_mandate_version_id='d2220000-0000-4000-8000-000000000001'where id='d2030000-0000-4000-8000-000000000001';
set local session_replication_role=origin;
grant usage on schema extensions to authenticated;
create temporary table bundle_results(kind text,value jsonb);grant select,insert on bundle_results to authenticated;
insert into public.catalog_releases(id,library_id,release_key,status,source_bundle_hash,created_by)values('f2033000-0000-4000-8000-000000000001','f2180000-0000-4000-8000-000000000010','BUNDLE.REVIEW.V1','DRAFT',repeat('a',64),'a2030000-0000-4000-8000-000000000001');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
insert into bundle_results select 'Q'||i,public.create_catalog_question('f2180000-0000-4000-8000-000000000010','BUNDLE_Q'||i,'LIBRARY',jsonb_build_object('label_fr','Question '||i,'label_ar','سؤال '||i,'answer_type','YES_NO','data_key','bundle.q'||i,'required_by_default',true,'required_for_quote',false,'required_for_publication',false,'options','[]'::jsonb,'validation_schema','{}'::jsonb,'sensitivity','BUSINESS','nullable',false,'weight',0,'maximum_score',0),'Question de recette','bundle-question-'||i)from generate_series(1,3)i;
insert into bundle_results values('RULE',public.create_catalog_rule('f2180000-0000-4000-8000-000000000010','BUNDLE_RULE',jsonb_build_object('condition_ast',jsonb_build_object('operator','EQ','question_version_id',(select value->>'version_id'from bundle_results where kind='Q1'),'value',true),'actions','[{"type":"HUMAN_REVIEW"}]'::jsonb,'dependency_graph','{}'::jsonb,'priority',10,'sensitive',false),'Règle de recette','bundle-rule-create'));
insert into bundle_results values('FORM',public.create_catalog_questionnaire('f2180000-0000-4000-8000-000000000010','f2033000-0000-4000-8000-000000000001','BUNDLE_FORM','{"title_fr":"Diagnostic nouveau","title_ar":"تشخيص جديد","description_fr":"Description de recette","description_ar":"وصف للاختبار","audience":"CLIENT","engine_version":"RULE_ENGINE_V1","policy_version":"POLICY_V1","sensitive":false,"section_key":"GENERAL","section_label_fr":"Questions générales","section_label_ar":"أسئلة عامة"}','Création du diagnostic','bundle-form-create'));
select lives_ok(format($sql$select public.save_franchise_questionnaire_composition(%L,'[{"key":"GENERAL","labelFr":"Questions générales","labelAr":"أسئلة عامة"},{"key":"MORE","labelFr":"Compléments","labelAr":"تكملة"}]',%L::jsonb,%L::jsonb,1,'bundle-compose-initial')$sql$,(select value->>'version_id'from bundle_results where kind='FORM'),(select jsonb_agg(jsonb_build_object('versionId',value->>'version_id','sectionKey',case when kind='Q2'then'MORE'else'GENERAL'end,'required',true)order by kind desc)from bundle_results where kind in('Q1','Q2','Q3')),(select jsonb_build_array(value->>'version_id')from bundle_results where kind='RULE')),'three newly created draft questions and draft rule compose with bilingual sections and actual order');
insert into bundle_results select'REQUEST1',public.submit_franchise_catalog_questionnaire((value->>'questionnaire_id')::uuid,(value->>'version_id')::uuid,1,2,'bundle-submit-initial')from bundle_results where kind='FORM';
select is((select count(*)from public.questionnaire_version_questions where questionnaire_version_id=(select(value->>'version_id')::uuid from bundle_results where kind='FORM')),3::bigint,'all three draft question versions are pinned in composition');
select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.catalog_questionnaire_review_queue(1)$$,'42501','CENTRAL_MFA_REQUIRED','central review queue requires AAL2');
select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal2"}',true);
select is((public.catalog_questionnaire_review_queue(1)->>'total')::int,1,'central queue includes new submitted bundle');
select is(jsonb_array_length(public.catalog_questionnaire_review_bundle((select(value->>'change_request_id')::uuid from bundle_results where kind='REQUEST1'))->'questions'),3,'human reviewer receives all bilingual child content');
select throws_ok(format($sql$select public.decide_catalog_change(%L,'APPROVE','Ancien parcours sans attestation',1,'bundle-legacy-draft-deny')$sql$,(select value->>'change_request_id'from bundle_results where kind='REQUEST1')),'55000','CATALOG_BUNDLE_REVIEW_REQUIRED','legacy approval explicitly refuses unreviewed draft children');
select is((select status from public.catalog_change_requests where id=(select(value->>'change_request_id')::uuid from bundle_results where kind='REQUEST1')),'IN_REVIEW','legacy refusal writes no approval state');
select throws_ok(format($sql$select public.decide_franchise_questionnaire_bundle(%L,'APPROVE','Sans confirmation FR AR',1,false,'bundle-no-confirmation')$sql$,(select value->>'change_request_id'from bundle_results where kind='REQUEST1')),'23514','CATALOG_TRANSLATION_CONFIRMATION_REQUIRED','approval requires explicit human confirmation of translations and child content');
insert into bundle_results select'REJECT',public.decide_franchise_questionnaire_bundle((value->>'change_request_id')::uuid,'REJECT','Corriger la première question avant publication',1,false,'bundle-reject-initial')from bundle_results where kind='REQUEST1';
select ok((select value->>'reviewProofHash'~'^[0-9a-f]{64}$'from bundle_results where kind='REJECT'),'rejection includes immutable reviewed snapshot proof without translation attestation');
select is((select status from public.questionnaire_versions where id=(select(value->>'version_id')::uuid from bundle_results where kind='FORM')),'DRAFT','rejected questionnaire returns to editable draft');
select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
insert into bundle_results select'Q1_EDIT',public.save_catalog_question_draft((value->>'question_id')::uuid,(value->>'version_id')::uuid,'LIBRARY','{"label_fr":"Question corrigée","label_ar":"سؤال مصحح","answer_type":"YES_NO","data_key":"bundle.q1","required_by_default":true,"required_for_quote":false,"required_for_publication":false,"options":[],"validation_schema":{},"sensitivity":"BUSINESS","nullable":false,"weight":0,"maximum_score":0}','Correction bilingue',1,1,'bundle-question-correction')from bundle_results where kind='Q1';
insert into bundle_results select'RULE_EDIT',public.save_catalog_rule_draft((value->>'rule_id')::uuid,(value->>'version_id')::uuid,jsonb_build_object('condition_ast',jsonb_build_object('operator','EQ','question_version_id',(select value->>'version_id'from bundle_results where kind='Q1_EDIT'),'value',true),'actions','[{"type":"HUMAN_REVIEW"}]'::jsonb,'dependency_graph','{}'::jsonb,'priority',10,'sensitive',false),'Référence corrigée',1,1,'bundle-rule-correction')from bundle_results where kind='RULE';
select lives_ok(format($sql$select public.save_franchise_questionnaire_composition(%L,'[{"key":"GENERAL","labelFr":"Questions générales corrigées","labelAr":"أسئلة عامة مصححة"}]',%L::jsonb,%L::jsonb,4,'bundle-compose-corrected')$sql$,(select value->>'version_id'from bundle_results where kind='FORM'),(select jsonb_agg(jsonb_build_object('versionId',value->>'version_id','sectionKey','GENERAL','required',true)order by kind)from bundle_results where kind in('Q1_EDIT','Q2','Q3')),(select jsonb_build_array(value->>'version_id')from bundle_results where kind='RULE_EDIT')),'rejection can be corrected with new question/rule snapshots and real reordered composition');
insert into bundle_results select'REQUEST2',public.submit_franchise_catalog_questionnaire((value->>'questionnaire_id')::uuid,(value->>'version_id')::uuid,3,5,'bundle-submit-corrected')from bundle_results where kind='FORM';
select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal2"}',true);
insert into bundle_results select'APPROVE',public.decide_franchise_questionnaire_bundle((value->>'change_request_id')::uuid,'APPROVE','FR et AR vérifiés ainsi que les trois questions et la règle',1,true,'bundle-approve-corrected')from bundle_results where kind='REQUEST2';
select is((select count(*)from public.questionnaire_version_questions l join public.question_versions q on q.id=l.question_version_id where l.questionnaire_version_id=(select(value->>'version_id')::uuid from bundle_results where kind='FORM')and q.status='PUBLISHED'and q.translation_review_status='APPROVED'),3::bigint,'explicit central review freezes all three reviewed question versions');
select is((select status from public.question_rule_versions where id=(select(value->>'version_id')::uuid from bundle_results where kind='RULE_EDIT')),'PUBLISHED','reviewed rule snapshot is published for immutable questionnaire use');
select is((select value from bundle_results where kind='APPROVE'),public.decide_franchise_questionnaire_bundle((select(value->>'change_request_id')::uuid from bundle_results where kind='REQUEST2'),'APPROVE','FR et AR vérifiés ainsi que les trois questions et la règle',1,true,'bundle-approve-corrected'),'bundle decision replay returns identical proof without duplicate writes');
select is((select count(*)from public.franchise_questionnaire_bundle_reviews where library_id='f2180000-0000-4000-8000-000000000010'),2::bigint,'rejection and later approval each have one immutable review snapshot');
select is((select review_snapshot->'questions'->0->>'label_fr'from public.franchise_questionnaire_bundle_reviews where change_request_id=(select(value->>'change_request_id')::uuid from bundle_results where kind='REQUEST1')),'Question 3','original rejected snapshot remains reproducible after correction and reordering');
select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
insert into bundle_results values('REFUSED_DIFF',public.franchise_catalog_review_diff('d2030000-0000-4000-8000-000000000001',(select(value->>'change_request_id')::uuid from bundle_results where kind='REQUEST1')));
select is((select(value->>'beforeVersion')::int from bundle_results where kind='REFUSED_DIFF'),1,'comparison uses rejected draft snapshot even when version UUID was retained');
select ok((select(value->>'beforeHash')is distinct from(value->>'afterHash')from bundle_results where kind='REFUSED_DIFF'),'rejected and corrected snapshot hashes are distinct');
select is((select change.value->'before'->0->>'label_fr'from bundle_results cross join lateral jsonb_array_elements(value->'changes')as change(value)where kind='REFUSED_DIFF'and change.value->>'field'='questions'),'Question 3','difference retains original question labels and order from human review evidence');
select is((select change.value->'after'->0->>'label_fr'from bundle_results cross join lateral jsonb_array_elements(value->'changes')as change(value)where kind='REFUSED_DIFF'and change.value->>'field'='questions'),'Question corrigée','difference shows actual corrected bilingual child content');
insert into bundle_results select'PUBLISHED',public.publish_questionnaire_version((value->>'version_id')::uuid,(select row_version from public.questionnaire_versions where id=(value->>'version_id')::uuid),'bundle-publish-corrected','f2039900-0000-4000-8000-000000000001')from bundle_results where kind='FORM';
select is((select value->>'outcome'from bundle_results where kind='PUBLISHED'),'QUESTIONNAIRE_VERSION_PUBLISHED','new questionnaire publishes through unchanged snapshot guard after human bundle review');
select ok((select value->>'snapshot_hash'~'^[0-9a-f]{64}$'from bundle_results where kind='PUBLISHED'),'published questionnaire has exact reproducibility hash');
insert into bundle_results select'LEGACY',public.clone_catalog_questionnaire((value->>'version_id')::uuid,'f2033000-0000-4000-8000-000000000001','BUNDLE_LEGACY','Clone avec dépendances déjà publiées','bundle-legacy-clone')from bundle_results where kind='FORM';
insert into bundle_results select'LEGACY_REQUEST',public.submit_franchise_catalog_questionnaire((value->>'questionnaire_id')::uuid,(value->>'version_id')::uuid,(select row_version from public.questionnaires where id=(value->>'questionnaire_id')::uuid),(select row_version from public.questionnaire_versions where id=(value->>'version_id')::uuid),'bundle-legacy-submit')from bundle_results where kind='LEGACY';
reset role;insert into public.platform_user_roles(user_id,role_code)values('a2030000-0000-4000-8000-000000000001','MATRICIA_ADMIN');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok(format($sql$select public.decide_franchise_questionnaire_bundle(%L,'APPROVE','Tentative auto approbation',1,true,'bundle-self-deny')$sql$,(select value->>'change_request_id'from bundle_results where kind='LEGACY_REQUEST')),'42501','CATALOG_SELF_APPROVAL_DENIED','even central role cannot approve own submitted bundle');
select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal2"}',true);
select lives_ok(format($sql$select public.decide_catalog_change(%L,'APPROVE','Parcours historique avec dépendances prêtes',1,'bundle-legacy-ready')$sql$,(select value->>'change_request_id'from bundle_results where kind='LEGACY_REQUEST')),'legacy central approval remains allowed for already published dependencies');
reset role;
select throws_ok($$update public.franchise_questionnaire_bundle_reviews set reason='Modification interdite'where change_request_id=(select(value->>'change_request_id')::uuid from bundle_results where kind='REQUEST2')$$,'55000','IMMUTABLE_CATALOG_REVIEW_SNAPSHOT','review proof cannot be rewritten');
select throws_ok($$update public.question_versions set label_fr='Modification interdite'where id=(select(value->>'version_id')::uuid from bundle_results where kind='Q1_EDIT')$$,'55000','IMMUTABLE_QUESTIONNAIRE_VERSION','published child content cannot be changed');
select is((select count(*)from public.audit_events where action='catalog.questionnaire.bundle_reviewed'and resource_id=(select value->>'questionnaire_id'from bundle_results where kind='FORM')),2::bigint,'each human bundle decision emits one audit event');
select is((select count(*)from public.event_outbox where event_type='QuestionnaireBundleReviewedV1'and aggregate_id=(select value->>'questionnaire_id'from bundle_results where kind='FORM')),2::bigint,'decision replay emits no extra bundle outbox events');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into bundle_results select'SENSITIVE_Q',public.save_catalog_question_draft((value->>'question_id')::uuid,(value->>'version_id')::uuid,'LIBRARY',(public.franchise_question_detail('d2030000-0000-4000-8000-000000000001',(value->>'question_id')::uuid)->'payload')||'{"sensitivity":"CONFIDENTIAL"}'::jsonb,'Nouvelle variante sensible',(select row_version from public.question_bank_questions where id=(value->>'question_id')::uuid),(select row_version from public.question_versions where id=(value->>'version_id')::uuid),'bundle-sensitive-variant')from bundle_results where kind='Q3';
insert into bundle_results select'SENSITIVE_FORM',public.clone_catalog_questionnaire((value->>'version_id')::uuid,'f2033000-0000-4000-8000-000000000001','BUNDLE_SENSITIVE','Clone avec contenu sensible réel','bundle-sensitive-clone')from bundle_results where kind='FORM';
select public.save_franchise_questionnaire_composition((select(value->>'version_id')::uuid from bundle_results where kind='SENSITIVE_FORM'),'[{"key":"GENERAL","labelFr":"Contenu sensible","labelAr":"محتوى حساس"}]',(select jsonb_agg(jsonb_build_object('versionId',value->>'version_id','sectionKey','GENERAL','required',true)order by kind)from bundle_results where kind in('Q1_EDIT','Q2','SENSITIVE_Q')),(select jsonb_build_array(value->>'version_id')from bundle_results where kind='RULE_EDIT'),(select row_version from public.questionnaire_versions where id=(select(value->>'version_id')::uuid from bundle_results where kind='SENSITIVE_FORM')),'bundle-sensitive-composition');
insert into bundle_results select'SENSITIVE_META',jsonb_build_object('identityRowVersion',(select row_version from public.questionnaires where id=(value->>'questionnaire_id')::uuid),'versionRowVersion',(select row_version from public.questionnaire_versions where id=(value->>'version_id')::uuid))from bundle_results where kind='SENSITIVE_FORM';
select set_config('request.jwt.claims','{"sub":"a2030000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok(format($sql$select public.save_franchise_questionnaire_composition(%L,'[{"key":"GENERAL","labelFr":"Retrait du contenu sensible","labelAr":"حذف محتوى حساس"}]',%L::jsonb,%L::jsonb,%s,'bundle-sensitive-removal-deny')$sql$,(select value->>'version_id'from bundle_results where kind='SENSITIVE_FORM'),(select jsonb_agg(jsonb_build_object('versionId',value->>'version_id','sectionKey','GENERAL','required',true)order by kind)from bundle_results where kind in('Q1_EDIT','Q2')),(select jsonb_build_array(value->>'version_id')from bundle_results where kind='RULE_EDIT'),(select(value->>'versionRowVersion')::int from bundle_results where kind='SENSITIVE_META')),'42501','CATALOG_SENSITIVE_MFA_REQUIRED','removing a sensitive source child still requires AAL2 even with parent flag false');
reset role;
select is((select count(*)from public.questionnaire_version_questions where questionnaire_version_id=(select(value->>'version_id')::uuid from bundle_results where kind='SENSITIVE_FORM')),3::bigint,'denied sensitive removal leaves complete source composition unchanged');
set local role authenticated;
select throws_ok(format($sql$select public.submit_franchise_catalog_questionnaire(%L,%L,%s,%s,'bundle-sensitive-submit-deny')$sql$,(select value->>'questionnaire_id'from bundle_results where kind='SENSITIVE_FORM'),(select value->>'version_id'from bundle_results where kind='SENSITIVE_FORM'),(select(value->>'identityRowVersion')::int from bundle_results where kind='SENSITIVE_META'),(select(value->>'versionRowVersion')::int from bundle_results where kind='SENSITIVE_META')),'42501','CATALOG_SENSITIVE_MFA_REQUIRED','submit derives sensitivity from actual children rather than optional parent flag');
reset role;
select ok(not has_function_privilege('anon','public.decide_franchise_questionnaire_bundle(uuid,text,text,integer,boolean,text,uuid)','EXECUTE'),'anonymous bundle review is denied');
select *from finish();rollback;
